from pathlib import Path
import copy,importlib.util,json,tempfile,unittest,shutil
ROOT=Path(__file__).resolve().parents[1]/'skills/build-assessments-and-evaluations'
spec=importlib.util.spec_from_file_location('engagement_validator',ROOT/'scripts/validate_engagement_package.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
BASE=json.loads((ROOT/'examples/engagement/package.json').read_text())
class Tests(unittest.TestCase):
 def setUp(self):self.d=copy.deepcopy(BASE)
 def errors(self):return v.validate_record(self.d,ROOT)
 def reject(self,phrase):self.assertTrue(any(phrase in e for e in self.errors()),self.errors())
 def consequential(self):self.d['intended_use']='Certification, job authorization and employment decision';self.d['stakes'].update(clarification_status='Pending',clarification_answer=None,clarified_use=None)
 def test_valid_draft(self):self.assertEqual(self.errors(),[])
 def test_consequential_stakes_require_clarification(self):self.consequential();self.reject('require clarification')
 def test_no_low_stakes_default_for_consequences(self):self.consequential();self.reject('cannot default to low stakes')
 def test_unresolved_decisions_blocked(self):self.d['stakes'].update(classification='unresolved',consequential_decisions_enabled=True);self.reject('cannot enable decisions')
 def test_consequential_governance_not_excluded(self):self.consequential();self.reject('governance check cannot be excluded')
 def test_practice_clarification_must_exclude_consequences(self):self.d['intended_use']='Certification assessment';self.d['stakes']['clarified_use']='consequential-decision';self.reject('explicit nonconsequential clarification')
 def test_no_implicit_global_pass(self):self.d['assets'][5]['classification']='Proficient';self.reject('absent decision rule cannot classify')
 def test_threshold_requires_authorized_standard(self):self.d['assets'][5]['decision_rule']=dict(threshold=4,standard_id='invented',critical_rule='all');self.reject('authorized standard')
 def test_critical_requirements_not_compensated(self):self.d['assets'][5]['decision_rule']=dict(threshold=4,standard_id='invented',critical_rule='total-only');self.reject('critical criteria cannot be compensated')
 def test_invalid_threshold(self):self.d['assets'][5]['decision_rule']=dict(threshold=99,standard_id='invented',critical_rule='all');self.reject('threshold invalid')
 def test_session_arithmetic(self):self.d['total_minutes']=85;self.reject('Agenda total differs')
 def test_break_not_instruction(self):self.d['instructional_minutes']=90;self.reject('instructional_minutes differs')
 def test_embedded_double_count(self):self.d['embedded_minutes']=90;self.reject('Embedded total differs')
 def test_parent_overload(self):self.d['assets'][0]['minutes']=9;self.reject('exceeds parent module')
 def test_overlap(self):self.d['assets'][2].update(parent_module='M-01',offset_minutes=0);self.reject('Embedded activities overlap')
 def test_additional_time_requires_reallocation(self):self.d['assets'][0]['placement']='additional';self.reject('requires parent agenda reallocation')
 def test_break_cannot_host_practice(self):self.d['assets'][0]['parent_module']='B-01';self.reject('parent must be instruction')
 def test_unknown_parent(self):self.d['assets'][0]['parent_module']='M-99';self.reject('parent must be instruction')
 def test_start_gap(self):self.d['agenda'][1]['start_minute']=9;self.reject('start minute mismatch')
 def test_unknown_objective(self):self.d['assets'][0]['objective_ids']=['O-99'];self.reject('unknown reference')
 def test_uncovered_objective(self):self.d['objectives'].append(dict(id='O-99',text='Unsupplied objective'));self.reject('coverage differs')
 def test_unknown_source(self):self.d['assets'][0]['source_ids']=['SRC-99'];self.reject('unknown reference')
 def test_missing_fact(self):self.d['assets'][4]['required_fact_quotes'].append('a nonexistent owner fact');self.reject('required fact missing')
 def test_unresolved_key_reference(self):self.d['assets'][2]['key_quote']='invented answer key';self.reject('answer key reference missing')
 def test_unknown_retry(self):self.d['assets'][5]['retry_asset_id']='RETRY-999';self.reject('unknown retry asset')
 def test_metadata_source_version(self):self.d['sources'][0]['version']='';self.reject('source version/locator')
 def test_metadata_owner(self):self.d['assets'][0]['owner']='';self.reject('metadata missing owner')
 def test_duplicate_assets(self):self.d['assets'][1]['id']='ENG-001';self.reject('unique')
 def test_fallback_loses_operation_construct(self):self.d['fallbacks'][0]['primary_construct']='Operate software';self.d['fallbacks'][0]['fallback_construct']='Recognize screenshots';self.reject('loses construct/evidence')
 def test_fallback_omits_evidence(self):self.d['fallbacks'][0]['omitted_evidence']=['actual record save'];self.reject('loses construct/evidence')
 def test_untested_fallback_cannot_claim_proficiency(self):self.d['fallbacks'][0]['proficiency_use_allowed']=True;self.reject('limited fallback cannot claim')
 def test_missing_fallback_rationale(self):self.d['fallbacks'][0]['rationale']='';self.reject('rationale required')
 def test_scoring_workload(self):self.d['observation']['total_scoring_minutes']=10;self.reject('workload differs')
 def test_sampling_not_individual_evidence(self):self.d['observation']['individual_collection']=False;self.reject('Sampling cannot establish')
 def test_unknown_results_stay_unknown(self):self.d['observation']['unobserved_result']='Proficient';self.reject('Sampling cannot establish')
 def test_selected_evaluation_needs_owner(self):self.d['evaluation'][0]['owner']='';self.reject('measure missing owner')
 def test_selected_evaluation_needs_action(self):self.d['evaluation'][0]['action']='';self.reject('measure missing action')
 def test_deferred_level_needs_rationale(self):self.d['evaluation'][1]['rationale']='';self.reject('unselected measure needs')
 def test_missing_quality_record(self):self.d['quality_checks'].pop();self.reject('twelve')
 def test_stale_review_evidence(self):self.d['quality_checks'][0]['artifact_version']='1.0';self.reject('metadata/version')
 def test_pass_needs_actual_evidence(self):self.d['quality_checks'][0]['evidence']=None;self.reject('actual evidence missing')
 def test_exclusion_not_pass(self):self.d['quality_checks'][-1]['status']='Pass';self.reject('exclusion cannot be Pass')
 def test_false_readiness(self):self.d['release_state']='Ready for use';self.reject('unperformed/failed checks');self.reject('blocking open items')
 def test_known_defect_state(self):self.d['quality_checks'][0]['status']='Needs revision';self.reject('Known defect requires')
 def test_handoff_destination(self):self.d['handoffs'][0]['destination']='different-builder';self.reject('destinations differ')
 def test_handoff_cannot_claim_execution(self):self.d['handoffs'][0]['status']='Executed';self.reject('cannot imply execution')
 def test_handoff_keeps_references(self):self.d['handoffs'][0]['asset_ids']=['missing-asset'];self.reject('unknown reference')
 def test_unsafe_path(self):self.d['assets'][0]['key_path']='../../../../../etc/passwd';self.reject('unsafe local path')
 def test_learner_key_separation(self):
  with tempfile.TemporaryDirectory() as t:
   p=Path(t);shutil.copytree(ROOT/'examples',p/'examples');f=p/'examples/engagement/learner-practice.md';f.write_text(f.read_text()+'\nFacilitator-only keys\n');self.assertTrue(any('contains key material' in e for e in v.validate_record(self.d,p)))
 def test_verified_fallback_needs_actual_evidence(self):self.d['fallbacks'][0]['verification_status']='Verified';self.reject('verified fallback evidence missing')
 def test_actual_decisions_need_ready_standard(self):self.d['stakes']['consequential_decisions_enabled']=True;self.reject('Actual decision use requires')
 def test_bad_record(self):self.assertTrue(v.validate_record([],ROOT))
if __name__=='__main__':unittest.main(verbosity=2)
